#include <iostream>
#include <iomanip>
int main() {
    long long price{}, count{};
    if (!(std::cin >> price >> count)) { std::cout << "invalid\n"; return 0; }
    std::cin >> std::ws;
    if (!std::cin.eof() || price < 0 || price > 100000 || count < 0 || count > 1000) { std::cout << "invalid\n"; return 0; }
    long long total = price * count;
    std::cout << "total=" << total / 100 << '.' << std::setfill('0') << std::setw(2) << total % 100 << '\n';
}
